import { defineConfig, devices } from '@playwright/test';

const port = 3100;

export default defineConfig({
  testDir: 'e2e',
  fullyParallel: false,
  workers: 1,
  retries: 0,
  timeout: 30_000,
  expect: { timeout: 5_000 },
  reporter: [
    ['list'],
    ['json', { outputFile: 'test-results/results.json' }],
    ['html', { open: 'never', outputFolder: 'playwright-report' }],
  ],
  use: {
    baseURL: `http://localhost:${port}`,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  webServer: {
    command: 'npm run build && npm start',
    url: `http://localhost:${port}/api/health`,
    env: { PORT: String(port) },
    reuseExistingServer: false,
    timeout: 120_000,
  },
  // Tests reset one store. Capture mobile explicitly without parallel mutations.
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'], viewport: { width: 1440, height: 900 } } }],
});

{
  "targets": [
    {
      "id": "catalog",
      "route": "/",
      "role": "renter",
      "purpose": "Renter browses the car marketplace grid with filters",
      "ready": "At least one [data-testid=car-card] visible and [data-testid=result-count] reads \"3 cars\"",
      "prepare": []
    },
    {
      "id": "booking",
      "route": "/cars/car_01",
      "role": "renter",
      "purpose": "Renter reviews car details and the live price breakdown before requesting a booking",
      "ready": "[data-testid=price-total] reads \"$280.00\" after dates are entered",
      "prepare": [
        "Fill [data-testid=booking-start] with 2026-12-01",
        "Fill [data-testid=booking-end] with 2026-12-04"
      ]
    },
    {
      "id": "requests",
      "route": "/owner/requests",
      "role": "owner",
      "purpose": "Owner reviews incoming booking requests with status badges",
      "ready": "[data-testid=booking-card][data-id=book_301] visible with a status-badge reading \"Confirmed\"",
      "prepare": []
    }
  ]
}

